SEC = [
 (132, 'కృత్యం 4.1 – పట్టిక 4.1', [
  'వస్తువు | రూపం | గట్టి/మెత్తని | సుత్తితో కొడితే | రాగి ముక్క | మెరుస్తుంది | గట్టి | చదునవుతుంది | అల్యూమినియం ముక్క | మెరుస్తుంది | గట్టి | చదునవుతుంది | ఇనుప మేకు | మెరుస్తుంది | గట్టి | చదునవుతుంది | బొగ్గు ముక్క | మెరవదు | అంత గట్టి కాదు | ముక్కలవుతుంది | గంధకం ముద్ద | మెరవదు | మెత్తని | ముక్కలవుతుంది | చెక్క దిమ్మ | మెరవదు | అంత గట్టి కాదు | చదునవదు, ముక్కలవదు',
  'ముగింపు: రాగి, అల్యూమినియం, ఇనుము స్తరణీయ లోహాలు; బొగ్గు, గంధకం పెళుసు; చెక్క రెండూ కాదు.']),
 (134, 'సమగ్ర దృష్టి – రాగి ముందు, ఇనుము తర్వాత ఎందుకు?', [
  '1. రాగి ప్రకృతిలో కొన్నిచోట్ల స్వేచ్ఛా స్థితిలో దొరుకుతుంది; దాని ఖనిజం నుండి తక్కువ వేడితోనే తీయవచ్చు. 2. ఇనుమును ఖనిజం నుండి తీయడానికి చాలా ఎక్కువ ఉష్ణోగ్రత, మెరుగైన కొలిమి కావాలి. 3. అందుకే రాగి ముందుగా, ఇనుము తర్వాత వాడుకలోకి వచ్చాయని భావిస్తారు.']),
 (136, 'కృత్యం 4.2 – ధ్వనిగుణం', [
  'లోహపు చెంచా, నాణెం – గణగణ మోగే శబ్దం. బొగ్గు ముక్క, చెక్క దిమ్మ – మొద్దు శబ్దం. ముగింపు: లోహాలకు ధ్వనిగుణం ఉంది.']),
 (140, 'కృత్యం 4.3 – ఉష్ణ వహనం', [
  '1. లోహపు చెంచా పైకొన ఎక్కువ వేడిగా ఉంటుంది. 2. లోహం ఉష్ణాన్ని బాగా ప్రసారం చేస్తుంది (మంచి వాహకం); చెక్క ఉష్ణ అధమ వాహకం.',
  'వంట పాత్రలకు వాడే లోహాలు: అల్యూమినియం, ఇనుము, రాగి, స్టీలు.']),
 (142, 'కృత్యం 4.4 – పట్టిక 4.2, తుప్పు ఊహ', [
  'వస్తువు | బల్బు | ముగింపు | అల్యూమినియం రేకు | వెలుగుతుంది | మంచి వాహకం | ఇనుప మేకు | వెలుగుతుంది | మంచి వాహకం | రాగి తీగ | వెలుగుతుంది | మంచి వాహకం | గంధకం ముద్ద | వెలగదు | అధమ వాహకం | బొగ్గు ముక్క | వెలగదు | అధమ వాహకం | పొడి చెక్క, రాయి, రబ్బరు, నైలాన్ తాడు | వెలగదు | అధమ వాహకాలు',
  'క్రమం: బల్బును వెలిగించినవన్నీ లోహాలే.',
  'ఇనుముపై గోధుమ పొర: గాలి, నీరు రెండూ తగిలినప్పుడు ఏర్పడుతుంది.']),
 (144, 'కృత్యం 4.5 – పట్టిక 4.3 (తుప్పు)', [
  'సీసా | నీరు | గాలి | పరిశీలన | A | లేదు | ఉంది (పొడి గాలి) | తుప్పు లేదు | B | ఉంది | లేదు | తుప్పు లేదు | C | ఉంది | ఉంది | తుప్పు పట్టింది',
  'ముగింపు: తుప్పు పట్టడానికి నీరు, గాలి రెండూ అవసరం. ఇనుము + ఆక్సిజన్ + నీరు → ఆర్ద్ర ఐరన్ ఆక్సైడ్ (తుప్పు).']),
 (148, 'కృత్యం 4.6 – మెగ్నీషియం రిబ్బన్', [
  '1. రిబ్బన్ మిరుమిట్లు గొలిపే తెల్లని మంటతో మండి తెల్లని పొడి (మెగ్నీషియం ఆక్సైడ్) గా మారుతుంది. 2. ఆ పొడిని గోరువెచ్చని నీటిలో కలిపిన ద్రావణం ఎర్ర లిట్మస్‌ను నీలిగా మారుస్తుంది; నీలి లిట్మస్ మారదు → క్షార స్వభావం.',
  'మెగ్నీషియం + ఆక్సిజన్ → మెగ్నీషియం ఆక్సైడ్. మెగ్నీషియం ఆక్సైడ్ + నీరు → మెగ్నీషియం హైడ్రాక్సైడ్. (పుస్తకంలో రెండో సమీకరణం “Magnesium + Water” అని ముద్రించారు; ఇక్కడ చర్య జరిపేది మెగ్నీషియం ఆక్సైడ్.)',
  'సోడియం లోహం కాబట్టి దాని ఆక్సైడ్ కూడా క్షార స్వభావం గలది.']),
 (150, 'కృత్యం 4.7, 4.8 – గంధకం', [
  '4.7) గంధకం మండి సల్ఫర్ డయాక్సైడ్ వాయువు ఏర్పడుతుంది. నీటిలో కరిగిన ద్రావణం నీలి లిట్మస్‌ను ఎరుపుగా మారుస్తుంది → ఆమ్లం (సల్ఫ్యూరస్ ఆమ్లం).',
  '4.8) గంధకం పొడిని నీటిలో వేస్తే ఏ చర్యా జరగదు – అలోహాలు సాధారణంగా నీటితో చర్య జరపవు.']),
 (154, 'అలోహాల అవసరం', [
  'ఆక్సిజన్ ఇతర ఉపయోగాలు: 1. ఇంధనాలు మండటానికి. 2. ఆసుపత్రుల్లో రోగులకు ఆక్సిజన్ సిలిండర్లు. 3. పర్వతారోహకులు, ఈతగాళ్లకు. 4. లోహాల వెల్డింగ్‌లో.']),
 (156, 'మన అభ్యసనాన్ని మెరుగుపరచుకుందాం – ప్ర.1–9', [
  '1) A) స్తరణీయత: కొట్టి పలుచని రేకులుగా చేయగల ధర్మం. B) తాంతవత: తీగలుగా సాగే ధర్మం. C) ధ్వనిగుణం: గణగణ శబ్దం చేసే ధర్మం. D) క్షయం: గాలి, నీరు, ఇతర పదార్థాల వల్ల లోహ ఉపరితలం క్రమంగా పాడవడం. E) తుప్పు పట్టడం: తడి గాలిలో ఇనుముపై గోధుమ రంగు పొర ఏర్పడే ప్రక్రియ.',
  '2) లోహాలు: 1. మెరుస్తాయి, స్తరణీయం, తాంతవం. 2. ఉష్ణ, విద్యుత్ మంచి వాహకాలు. | అలోహాలు: 1. మెరుపు ఉండదు, పెళుసు. 2. ఉష్ణ, విద్యుత్ అధమ వాహకాలు.',
  '3) D – తాంతవత, విద్యుత్ వాహకత రెండూ.',
  '4) D – సోడియం.',
  '5) 1. బంగారం, వెండి, ప్లాటినం చాలా మెరుస్తాయి. 2. అవి అత్యంత స్తరణీయం, తాంతవం – సన్నని నగిషీ చేయవచ్చు. 3. గాలి, నీటితో సులభంగా చర్య జరపవు – రంగు/మెరుపు పోదు. చాలా ఇతర లోహాలు క్షయం చెందుతాయి.',
  '6) 1. మెగ్నీషియం + ఆక్సిజన్ → మెగ్నీషియం ఆక్సైడ్ (తెల్లని పొడి). 2. గంధకం + ఆక్సిజన్ → సల్ఫర్ డయాక్సైడ్ (వాయువు). 3. తేడా: మెగ్నీషియం ఆక్సైడ్ ద్రావణం క్షారం (ఎర్ర లిట్మస్ → నీలి); సల్ఫర్ డయాక్సైడ్ ద్రావణం ఆమ్లం (నీలి లిట్మస్ → ఎరుపు).',
  '7) వేడి చేస్తే ఇనుము ఎర్రగా కాలి మెత్తబడుతుంది; అప్పుడు సుత్తితో కొట్టి కావలసిన ఆకారంలోకి సులభంగా మలచవచ్చు.',
  '8) A – అమర్ మాత్రమే సరి (మెగ్నీషియం ఆక్సైడ్ ద్రావణం క్షారం).',
  '9) A – అల్యూమినియం.']),
 (158, 'ప్ర.10–13', [
  '10) (i) – (c) COPPER (రాగి); (ii) – (e) GOLD (బంగారం); (iii) – (a) OXYGEN (ఆక్సిజన్); (iv) – (d) NITROGEN (నైట్రోజన్); (v) – (b) CHLORINE (క్లోరిన్).',
  '11) C – సిలికా జెల్ తేమను పీల్చేస్తుంది; తేమ లేకపోవడం వల్ల మేకు తుప్పు పట్టదు.',
  '12) నూనెలో ముంచిన మేకు తుప్పు పట్టదు. కారణం: నూనె పొర గాలి, తేమ మేకును తాకకుండా అడ్డుకుంటుంది. నీటిలో, వెనిగర్‌లో ఉన్న మేకులు తుప్పు పడతాయి (వెనిగర్ ఆమ్లం – ఇంకా వేగంగా).',
  '13) మెగ్నీషియం + గాలి + ఉష్ణం → బూడిద (మెగ్నీషియం ఆక్సైడ్) → నీరు కలిపితే → మెగ్నీషియం హైడ్రాక్సైడ్ ద్రావణం. నీలి లిట్మస్ ద్రావణం: మార్పు లేదు (నీలిగానే); ఎర్ర లిట్మస్ ద్రావణం: నీలి.']),
 (160, 'ప్ర.14–17, ప్రాజెక్టులు', [
  '14) 1. స్తరణీయత → రేకులు, పాత్రలు. 2. తాంతవత + విద్యుత్ వాహకత → విద్యుత్ తీగలు. 3. ఉష్ణ వాహకత → వంట పాత్రలు. 4. ధ్వనిగుణం → గంటలు. 5. బలం → వంతెనలు, పనిముట్లు. 6. అలోహాలు: ఆక్సిజన్ – శ్వాస; క్లోరిన్ – నీటి శుద్ధి; నైట్రోజన్ – ఎరువులు; అయోడిన్ – యాంటీసెప్టిక్; ప్లాస్టిక్/రబ్బరు వంటి బంధకాలు – పిడులు.',
  '15) (i) F – అల్యూమినియం, రాగి లోహాలు. (ii) F – లోహ ఆక్సైడ్ల ద్రావణం క్షారం; ఎర్ర లిట్మస్‌ను నీలిగా మారుస్తుంది. (iii) T – ఆక్సిజన్ అలోహం, శ్వాసక్రియకు అవసరం. (iv) F – రాగి ఉష్ణానికి మంచి వాహకం కాబట్టి వాడతారు.',
  '16) రాగి (లేదా ఇనుము). కారణాలు: 1. లోహం – ఉష్ణానికి మంచి వాహకం, నీరు త్వరగా మరుగుతుంది. 2. స్తరణీయం – పాత్ర ఆకారంలోకి మలచవచ్చు. 3. గంధకం, బొగ్గు పెళుసు, మండుతాయి; ప్లాస్టిక్ కరుగుతుంది; చెక్క, అట్ట కాలిపోతాయి, ఉష్ణ అధమ వాహకాలు.',
  '17) వాడలేం. కారణాలు: 1. గంధకం పెళుసు – స్తరణీయం కాదు, పలుచని గట్టి పూతగా ఇనుముకు అతకదు. 2. తేలికగా రాలిపోతుంది, మండే స్వభావం గలది. జింక్ లోహం కాబట్టి ఇనుముపై గట్టి పొరగా నిలుస్తుంది.',
  'ప్రాజెక్టు: ధోక్రా – ఛత్తీస్‌గఢ్, పశ్చిమ బెంగాల్, ఒడిశా; బిద్రీ – కర్ణాటక (బీదర్); పెంబర్తి – తెలంగాణ; కామరూపి – అస్సాం.']),
]
